            candidate = tuple((n >> (dimension - i - 1)) & 1 for i in range(dimension))
            if candidate not in self._model.probed_positions and candidate not in self._model.forbidden_positions:
                next_guess = list(candidate)
                break

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=next_guess, type='custom')]
        )

