    def __init__(self, model):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        dimension = data['dimension']
        num_particles = data['num_particles']
        distance = data['distance']
        prev_guess = data['guess']
        is_particle = data['is_particle']

        # Retrieve state
        found_particles = getattr(self._model, 'found_particles', [])
        probed = set(getattr(self._model, 'probed_positions', []))

        # Update state with previous guess
        if prev_guess is not None:
            prev_tuple = tuple(prev_guess)
            probed.add(prev_tuple)
            if is_particle:
                found_particles.append(prev_guess)

        next_guess = None

        if not found_particles:
            # Initial probes: all 0s then all 1s
            zero_candidate = [0]*dimension
            if tuple(zero_candidate) not in probed:
                next_guess = zero_candidate
            else:
                ones_candidate = [1]*dimension
                if tuple(ones_candidate) not in probed:
                    next_guess = ones_candidate
                else:
                    # Fallback linear scan (for small dimensions)
                    for i in range(2**dimension):
                        candidate = [int(b) for b in f'{i:0{dimension}b}']
                        if tuple(candidate) not in probed:
                            next_guess = candidate
                            break
        else:
            # Check complement of first found particle first
            first_particle = found_particles[0]
            complement = [1-b for b in first_particle]
            comp_valid = True
            for p in found_particles:
                if hamming_distance(complement, p) < distance:
                    comp_valid = False
                    break
            if comp_valid and tuple(complement) not in probed:
                next_guess = complement
            else:
                # Generate candidates with increasing flip distances
                current = first_particle
                for flip_dist in range(distance, dimension+1):
                    for bits in combinations(range(dimension), flip_dist):
                        candidate = current.copy()
                        for b in bits:
                            candidate[b] = 1 - candidate[b]
                        cand_tuple = tuple(candidate)
                        if cand_tuple in probed:
                            continue
                        valid = all(hamming_distance(candidate, p) >= distance for p in found_particles)
                        if valid:
                            next_guess = candidate
                            break
                    if next_guess:
                        break
            # Final fallback
            if not next_guess:
                for i in range(2**dimension):
                    candidate = [int(b) for b in f'{i:0{dimension}b}']
                    cand_tuple = tuple(candidate)
                    if cand_tuple not in probed and all(hamming_distance(candidate, p) >= distance for p in found_particles):
                        next_guess = candidate
                        break

        # Save state
        self.update_model_field('found_particles', found_particles)
        self.update_model_field('probed_positions', list(probed))

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=next_guess, type='custom')]
        )

